#!/bin/bash
# Mise a jour liliaa.tech - 13 nov 2026 (Claude) : menu de langue FR/NL/EN + actus du 13/11
set -e
OK1=b4d9a133a0503900decaf1a7a7d8d843   # version du 12/11
OK2=2c65d45783d551ed060e4028fc6b4354   # version precedente
LIVE=""
for f in $(find /var/www /srv /home /root /opt /usr/share/nginx /docker -name index.html -size -900k 2>/dev/null); do
  m=$(md5sum "$f" | cut -d' ' -f1)
  if [ "$m" = "$OK1" ] || [ "$m" = "$OK2" ]; then LIVE="$f"; break; fi
done
if [ -z "$LIVE" ]; then echo "STOP : page en ligne introuvable ou modifiee depuis. Rien n'a ete change."; exit 1; fi
D=$(dirname "$LIVE"); T=$(date +%Y%m%d-%H%M)
cp -p "$LIVE" "$D/index.backup-$T.html"
[ -f "$D/actus.json" ] && cp -p "$D/actus.json" "$D/actus.backup-$T.json"
base64 -d > "$D/index.new" <<'B64'
